    for color in set(counts) - {background}:
        points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not points:
            continue
        top = min(r for r, c in points)
        bottom = max(r for r, c in points)
        stroke_cols = [c for c in range(w) if any(grid[r][c] == color and grid[r+1][c] == color for r in range(h-1))]
        if stroke_cols:
            left, right = min(stroke_cols), max(stroke_cols)
            # Complete the top and bottom horizontal borders between vertical strokes.
            for r in {top, bottom}:
                for c in range(left, right + 1):
                    if grid[r][c] == background:
                        out[r][c] = 2
            # Complete each established vertical stroke between the borders.
            for c in stroke_cols:
                for r in range(top, bottom + 1):
                    if grid[r][c] == background:
                        out[r][c] = 2
        # Repair horizontal strokes that already contain a contiguous pair.
        for r in range(h):
            cols = [c for c in range(w) if grid[r][c] == color]
            has_run = any(grid[r][c] == color and grid[r][c+1] == color for c in range(w-1))
            if len(cols) > 1 and has_run:
                for c in range(min(cols), max(cols) + 1):
                    if grid[r][c] == background:
                        out[r][c] = 2
    return out
